import{_ as e,o as t,c as s,a2 as o}from"./chunks/framework.F7eQ-ohH.js";const p="/bzygq/assets/quesion_imgs_0b19e758f383439596dcd6ec035482b5.Bu7pFHPM.png",r="/bzygq/assets/quesion_imgs_792b68e6183c47598d68e36fd22ef19b.B0407pVx.png",i="/bzygq/assets/quesion_imgs_fcd15f58be7341539f32a06c9bbcc818.BqRJhYt8.png",n="/bzygq/assets/quesion_imgs_82100832c472422d950a23d9887d2900.DqObkEoW.png",b=JSON.parse('{"title":"SWTO分析法制定个人规划","description":"","frontmatter":{},"headers":[],"relativePath":"docs/前言/4.SWTO分析法制定个人规划.md","filePath":"docs/前言/4.SWTO分析法制定个人规划.md","lastUpdated":1788881428000}'),l={name:"docs/前言/4.SWTO分析法制定个人规划.md"};function d(h,a,c,_,u,T){return t(),s("div",null,[...a[0]||(a[0]=[o('<h1 id="swto分析法制定个人规划" tabindex="-1"><strong>SWTO分析法制定个人规划</strong> <a class="header-anchor" href="#swto分析法制定个人规划" aria-label="Permalink to &quot;**SWTO分析法制定个人规划**&quot;">​</a></h1><h2 id="swto分析法制定个人规划-1" tabindex="-1">SWTO分析法制定个人规划 <a class="header-anchor" href="#swto分析法制定个人规划-1" aria-label="Permalink to &quot;SWTO分析法制定个人规划&quot;">​</a></h2><p>最近很多小伙伴问我怎么来制定自己的秋招学习计划，他们大多数很纠结有的是因为技术方向不好，比如一开始走了前端但是看到后台岗位更多想换后台。有的则是吃不了学技术的苦，看见代码就头疼，问我到底该不该all in考试路线。</p><p>看到这些提问我也想起了自己在校期间哪种焦虑的状态，准备了很多东西但是后面想想好像没啥用，如果当初能有个人指导一下朝着正确的方向去准备秋招、进入职场是不是现在自己的发展又会好一些呢？</p><p>正是发现大家面临着这样的职业规划、技术方向选择、准备路线选择上的疑虑，这里给大家介绍一种SWTO分析法，帮助大家明确自己的目标，更加有的放矢。</p><h2 id="什么是swto分析法" tabindex="-1">什么是SWTO分析法？ <a class="header-anchor" href="#什么是swto分析法" aria-label="Permalink to &quot;什么是SWTO分析法？&quot;">​</a></h2><p>SWTO分析法是由哈佛大学商学院的企业战略决策教授安德鲁斯(K.Andrens)在20世纪60年代提出来的，一开始是用于商业领域、管理领域分析公司，产品，项目或个人（职业）战略审查、处境状况和方向趋势。</p><p>从字面上来解释，SWOT是优势(Strengths)、弱点(Weaknesses)、机会(Opportunities)和威胁(Threats)四个单词的缩写，将一件事情、一个决策目标拆分成为了优势、弱点、机会和威胁四个维度，帮我们理顺了做规划、决策时候的基本思路。</p><p>从整体上看SWOT可以分为两部分：第一部分为SW，主要用来分析内部条件，着眼于个人的实际情况进行分析；第二部分为OT，主要用来分析外部条件，强调外部环境的分析。通过SWOT分析方法可以确定个人自身的优劣势、机会和威胁，从而将自己的秋招学习计划的制定与自身的具体条件和外部的实际情况有机的结合起来。</p><h2 id="如何使用swto分析法" tabindex="-1">如何使用SWTO分析法？ <a class="header-anchor" href="#如何使用swto分析法" aria-label="Permalink to &quot;如何使用SWTO分析法？&quot;">​</a></h2><h3 id="构建swto矩阵" tabindex="-1">构建SWTO矩阵 <a class="header-anchor" href="#构建swto矩阵" aria-label="Permalink to &quot;构建SWTO矩阵&quot;">​</a></h3><p><img src="'+p+'" alt=""></p><p>如上图所示，这里我们以星球一个真实的小伙伴的提问为栗子来分析他到底该怎么样去准备和安排自己的秋招学习计划，以及秋招的重点准备路线是什么，这个小伙伴的完整提问如下：</p><p>我现在是一名准备秋招的211本科学生，对于方向有点迷茫，看看请问能不能给我一点建议就是我的本科是计算机专业的，但是我的大学期间很大一部分精力都放在了关于深度学习的项目上，导致我的技能大部分都是ai方向的，项目有第一发明人的专利，也有一作的论文在sci一区在投，然后实习的经历也都是ai方向。本人对开发方面的学习就比较少了。我是比较想秋招去找国企的工作，但是我现在去秋招去找ai方向的岗位的话感觉学历基本都到不了门槛，报计算机开发岗位的话项目实习等又不对口，我是也有准备去申香港的研但也不一定能申到ai，那现在我去秋招是应该专注于哪个方向呢？</p><p><strong>（1）分析优势</strong></p><p>我们先来看看这位同学有哪些优势，首先本科211的话现在这行情还是跨过了很多国企的基本门槛。其次，计算机本身也是一个优势，可能各位计算机的小伙伴不太觉得，其实真的计算机算是央企、国企、公务员和私企都能去的专业，选择范围很广。专业技能上上会AI算法、发明专利、sci一区在投递和实习经历，这个东西其实算优势也算劣势，优势在于至少会一门技术栈，劣势在于招聘算法的少。还有一个优势，就是他说能去申港硕，但是不能申AI，这说明这个同学家庭条件和资源都还挺不错的。</p><p>（2）劣势分析</p><p>这位同学的劣势的话也不是特别明显，主要是3点，第一，开发岗位不对口，因为没学过相关的技术栈；第二，AI岗位的要求高，竞争激烈、神仙打架，自己有可能过不了简历筛，面试也面不过；第三，港硕能申请，但是申请不到AI（这个我觉得不算啥劣势吧）。</p><p><strong>（3）机会分析</strong></p><p>私企、国企的AI岗位可以投递，虽然难度大要求高，但是确实是有机会的；不要求技术的国企可以投，例如中国兵器，航空航天里面一些央企，对技术的要求并不高，学校做的无论是深度学习还是啥项目都是可以拿去面试的。垄断类、公务员、选调生和事业单位的考试可以参加。</p><p>（4）威胁/风险分析</p><p>其实这些机会对于他来说威胁就一个，那就是竞争太激烈，导致拿不到offer。</p><h2 id="制定个人战略计划" tabindex="-1">制定个人战略计划 <a class="header-anchor" href="#制定个人战略计划" aria-label="Permalink to &quot;制定个人战略计划&quot;">​</a></h2><p>个人战略计划的制定包含战略制定（方针、目标），战术（路线图）和战法（步骤）3个部分，运用前面分析的优劣势和风险，可以得出个人未来发展的一系列的可选择项目，然后再根据这些可选择项来做决策。</p><h3 id="战略制定" tabindex="-1">战略制定 <a class="header-anchor" href="#战略制定" aria-label="Permalink to &quot;战略制定&quot;">​</a></h3><p><strong>（1）制定个人战略计划的基本思路</strong></p><ul><li>发挥优势：突出自己的优势因素，避开自己劣势的因素，人只有做自己擅长的事情未来的收获才会更大。</li><li>规避威胁：认真考虑计划制定过程中的风险因素，想办法去规避这些风险，实在没办法规避的，只有将风险降低到最低。</li></ul><p><strong>（2）SWOT分析法中包含着四种竞争战略</strong></p><p><img src="'+r+'" alt=""></p><ul><li>SO战略——增长型战略：只考虑优势和机会，制定计划的时候完全朝着发展的最大可能性去准备，这样的策略好处在于能够集中精力到少数几点，坏处是一旦失败抗风险能力低。对应到这个同学的栗子来说就是，集中精力去做最有优势的点AI算法岗，并且该岗位的发展是最好的，卷赢了就啥都有了。</li><li>WO战略——扭转型战略：W是弱点，O是机会，这个策略的核心在于直面劣势，使用劣势去寻找机会。对于这个同学来说就是硬刚Java后台软开岗位，在几个月的时间里面去把Java技术系统学一遍，再秋招，这样做的话风险会很大。</li><li>ST战略——多种经营型战略：S是优势，T是威胁和风险，充分考虑优势和风险做出最佳决策，这是我个人比较推崇的策略。对应到这个同学的栗子就是，既然所有的竞争都很激烈，那么不如根据自己的优势计算机专业、AI算法、港硕、学习能力，都去准备一下，广撒网，重点捕捞。</li><li>WT战略——防御型战略：W是弱点、T是威胁，这个方案太过于保守了，只考虑风险不考虑机会。对应到这个同学的案例上，可能就是随便找个私企有份工作就行了，对自己处于一种完全放弃的状态。</li></ul><p>（3）根据个人的风险偏好来制定计划</p><p>如上面所示，针对SWTO四种维度的组合可以得到不同风险类型的决策方案，up主个人在做计划或者是给大家给出建议的时候，一般比较常采用的就是“ST战略——多种经营性战略”，这个战略会充分分析你的优势和劣势，来做出决策。按照ST战略，针对这个同学制定的战略计划应该是：</p><p>1、发挥211本科学历优势，在校积累的AI算法岗方面的优势，积累准备各种私企、国企的算法岗面试；</p><p>2、港硕继续跟进申请流程，及时不能去AI算法方向，也能多一些准备职业发展规划的时间；</p><p>3、考试类央国企，如银行，运营商等可以作为备份的选择，花一定时间来准备扩大上岸范围。</p><h2 id="战术制定-路线图" tabindex="-1">战术制定（路线图） <a class="header-anchor" href="#战术制定-路线图" aria-label="Permalink to &quot;战术制定（路线图）&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>如图，针对上面的风险偏好，给这个同学制定了个人的战术路线图，主要的准备方向是AI算法岗、港硕和考试类央企，在这一部分需要将这些方向的具体准备内容和选择范围列举出来，方便大家后续去制定个人的学习计划</p><h2 id="战法制定-复习计划" tabindex="-1">战法制定（复习计划） <a class="header-anchor" href="#战法制定-复习计划" aria-label="Permalink to &quot;战法制定（复习计划）&quot;">​</a></h2><p>在战略计划制定完毕之后，就需要根据战术路线来分别制定各个路线的具体的，落到实处的复习计划。这里由于AI算法岗、考试类央企和港硕是3个不同方向，up主主要根据考试类央企来进行举例，首先我们进行问题拆分，如下：</p><p><img src="'+n+'" alt=""></p><p>除了上面战法制定的脑图之外，其实还需要进一步细化复习时间表，这部分安排在后面的文档专门给大家讲解。</p><h2 id="end" tabindex="-1">END <a class="header-anchor" href="#end" aria-label="Permalink to &quot;END&quot;">​</a></h2><p>SWTO分析方法实际上是一种企业管理的分析方法，用于企业在瞬息万变的资本市场上做出正确的决策，是一种经受过实践检验的方法。</p><p>用这种方法来做个人的秋招计划、职业规划的话是非常实用也非常有效的，同时大家可以根据自己不同的风险偏好类型来做出不同的决策，再制定相应的复习计划。</p>',45)])])}const m=e(l,[["render",d]]);export{b as __pageData,m as default};
